def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    count = 2

    if count == 0:
        return None

    average_net_revenue = (v1 + v2) / count

    return {
        "value": average_net_revenue,
        "trace": {
            "v1": v1,
            "v2": v2,
            "count": count,
            "average_net_revenue": average_net_revenue,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "currency"
            }
        }
    }
